let poolNotes={};try{poolNotes=JSON.parse(localStorage.getItem('hypercubic-pool-comments')||'{}')}catch{}
function companyItems(){return [...knowledgeRecords.filter(r=>r.pool).map(r=>({id:r.id,title:r.pool.title,author:'user',role:'Knowledge contributor',type:'Cases',price:'Paid',own:true,subscribed:false,summary:r.pool.summary,steps:r.pool.steps,answers:r.pool.answers,code:r.pool.code,users:[],comments:[],revision:r.pool.revision})),...poolExamples]}
function poolItem(){return companyItems().find(r=>r.id===kb.poolItem)}
function poolBadge(r){return r.price==='Free'?'Free':r.subscribed?'Paid · Company subscribed':'Paid · Not subscribed'}
function initials(name){return name.split(' ').map(s=>s[0]).join('').slice(0,2)}
function poolMarkup(){const item=poolItem();return `<section class="company-pool">${item?poolDetail(item):poolDirectory()}</section>`}
function poolDirectory(){const items=companyItems().filter(r=>(!kb.poolTab||kb.poolTab==='All knowledge'||kb.poolTab==='My uploads'&&r.own||kb.poolTab==='Subscribed'&&r.subscribed)&&(!kb.poolSearch||(r.title+' '+r.author+' '+r.type).toLowerCase().includes(kb.poolSearch.toLowerCase())));return `<header class="pool-heading"><span class="eyebrow">YOUR COMPANY'S SHARED KNOWLEDGE</span><h1>Knowledge pool</h1><p>Experience from the people you work with. Ready to put into practice.</p><span class="demo-label">Demo company · Sample experts and activity</span></header><div class="pool-toolbar"><div class="pool-tabs">${['All knowledge','My uploads','Subscribed'].map(t=>`<button data-action="pool-tab:${t}" class="${(kb.poolTab||'All knowledge')===t?'active':''}">${t}</button>`).join('')}</div><form id="pool-search-form"><input id="pool-search" aria-label="Search pool" placeholder="Search skills, experts, or topics" value="${esc(kb.poolSearch||'')}"><button aria-label="Search pool">${icon('search')}</button></form></div><div class="pool-list-header"><span>${items.length} knowledge skills</span><span>Expert contributions</span></div><div class="pool-grid">${items.map(r=>`<button class="skill-card" data-action="pool-open:${r.id}"><div class="skill-top"><span>${r.type}</span><span>${r.price}</span></div><h2>${esc(r.title)}</h2><p>${esc(r.summary)}</p><div class="skill-author"><span class="expert-avatar">${initials(r.author)}</span><span><strong>${r.own?'You':r.author}</strong><small>${r.role}</small></span></div><footer><span>${r.subscribed?'◉ Company subscribed':r.own?'Your upload · Owner access':'○ '+(r.price==='Free'?'Available to everyone':'Subscription required')}</span><span>↗</span></footer></button>`).join('')||'<div class="pool-empty"><h2>No matching knowledge yet.</h2><p>Try another search or upload a case from Knowledge.</p></div>'}</div>`}
function poolDetail(r){const canDownload=r.own||r.subscribed;const comments=[...r.comments,...(poolNotes[r.id]||[])];return `<button class="pool-back" data-action="pool-back">← Back to pool</button><div class="skill-detail-heading"><div><span class="eyebrow">${r.type} · ${r.id.startsWith('example')?'EXAMPLE SKILL':'YOUR UPLOAD'}</span><h1>${esc(r.title)}</h1><p>${esc(r.summary)}</p><div class="skill-author"><span class="expert-avatar">${initials(r.author)}</span><span><strong>${r.own?'You':r.author}</strong><small>${r.role} · Version ${r.revision||1}</small></span></div></div><div class="skill-primary-actions"><button class="button primary" data-action="pool-download:${r.id}" ${canDownload?'':'disabled'}>${icon('down')} Download skill</button><small>${r.own?'Author access · Free download':canDownload?'Included with your access':'Company subscription required'}</small>${r.own&&!r.id.startsWith('example')?`<button class="button" data-action="pool-edit:${r.id}">Edit & manage</button>`:''}</div></div><div class="detail-metrics"><article><span>ACCESS</span><strong>${r.own?'You own this skill':canDownload?'Download available':'Preview only'}</strong><p>${r.own?'Downloading your own knowledge is free, regardless of the company’s subscription.':'Access follows the skill’s availability.'}</p></article><article><span>COMPANY SUBSCRIPTION</span><strong>${r.subscribed?'Active · Paid by company':r.price==='Free'?'Free · No payment needed':'Not subscribed'}</strong><p>${r.subscribed?'Covered by the company knowledge plan.':r.price==='Free'?'Available without a paid subscription.':'The company has not paid for access to this skill.'}</p></article><article><span>USAGE</span><strong>${r.users.length} people used this</strong><p>${r.id.startsWith('example')?'Illustrative usage for user testing.':'No usage recorded yet.'}</p></article></div><div class="skill-detail-columns"><div><section class="detail-section"><h2>Inside this skill</h2><ol>${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${r.answers?`<details><summary>Captured reasoning & validation</summary>${r.answers.map(a=>`<p>${esc(a)}</p>`).join('')}</details>`:''}</section><section class="detail-section"><h2>Comments & questions <span>${comments.length}</span></h2>${comments.map(c=>`<article class="pool-comment"><span class="expert-avatar">${initials(c.author)}</span><div><strong>${esc(c.author)}</strong><small>${esc(c.kind)} · ${r.id.startsWith('example')?'Demo activity':'This browser'}</small><p>${esc(c.text)}</p></div></article>`).join('')||'<p class="muted">No comments yet. Start a conversation about this knowledge.</p>'}<form id="pool-comment-form"><div><select name="kind" aria-label="Contribution type"><option>Question</option><option>Comment</option></select><span>Posting as user</span></div><textarea name="text" aria-label="Your comment or question" placeholder="Ask a question or share how you used this skill…" required maxlength="2000"></textarea><button class="button primary">Post</button><small>Prototype · Comments stay in this browser</small></form></section></div><aside class="skill-activity"><h2>Used by</h2>${r.users.map((name,i)=>`<div class="activity-person"><span class="expert-avatar">${initials(name)}</span><span><strong>${name}</strong><small>${['Applied in a work session','Downloaded the skill','Used in a team handover'][i%3]}</small></span></div>`).join('')||'<p class="muted">People will appear here when usage is available.</p>'}<div class="activity-note">${r.id.startsWith('example')?'This skill, subscription, and activity are demo examples.':'Subscription and usage are prototype states; no billing is connected.'}</div></aside></div>`}
const bindKnowledgeBase=bindKnowledge;
bindKnowledge=function(){bindKnowledgeBase();const pricing=document.querySelector('#pool-pricing');if(pricing)pricing.onchange=e=>{currentKnowledge().pricing=e.target.value;persistKnowledge()};const search=document.querySelector('#pool-search-form');if(search)search.onsubmit=e=>{e.preventDefault();kb.poolSearch=document.querySelector('#pool-search').value;render()};const form=document.querySelector('#pool-comment-form');if(form)form.onsubmit=e=>{e.preventDefault();const data=new FormData(form),text=String(data.get('text')).trim();if(!text)return;(poolNotes[kb.poolItem]??=[]).push({author:'user',kind:String(data.get('kind')),text});try{localStorage.setItem('hypercubic-pool-comments',JSON.stringify(poolNotes))}catch{}render()}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action^="pool-"]');if(!b||b.disabled)return;const [action,id]=b.dataset.action.split(':');if(action==='pool-open'){kb.poolItem=id;kb.view='pool';kb.drawer=null;kb.poolNotice=null;history.replaceState(null,'','#pool')}if(action==='pool-back'){kb.poolItem=null}if(action==='pool-tab'){kb.poolTab=id}if(action==='pool-dismiss')kb.poolNotice=null;if(action==='pool-edit'){kb.id=id;kb.view='map';kb.drawer='edit'}if(action==='pool-download'){const r=companyItems().find(r=>r.id===id);if(!r||!(r.own||r.subscribed))return;const text=`---\nname: ${r.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}\ndescription: ${JSON.stringify(r.summary)}\n---\n\n# ${r.title}\n\n${r.id.startsWith('example')?'Illustrative prototype skill. Review before real use.':'Captured knowledge, reviewed by its author.'}\n\n## Steps\n${r.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\n${r.answers?'## Reasoning and validation\n'+r.answers.join('\n\n'):''}\n${r.code?'## Captured code\n```\n'+r.code+'\n```':''}`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download='SKILL.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Skill downloaded as SKILL.md.');return}render()});
if(state.screen==='knowledge')render();
let savedDownloads=[];try{savedDownloads=JSON.parse(localStorage.getItem('hypercubic-downloads')||'[]')}catch{}
function skillVersions(r){if(r.id==='example-own')return [{...r,revision:3,versionNote:'Added downstream reconciliation and handover guidance.'},{...r,revision:2,steps:r.steps.slice(0,2),versionNote:'Added downstream job checks.'},{...r,revision:1,steps:[r.steps[0]],versionNote:'Initial checkpoint restart guide.'}];if(r.id.startsWith('example'))return [{...r,revision:1,versionNote:'Initial publication.'}];const record=knowledgeRecords.find(k=>k.id===r.id);return [{...r,versionNote:'Current published version.'},...(record?.poolHistory||[]).map(v=>({...r,...v,versionNote:'Previously published version.'}))].sort((a,b)=>(b.revision||1)-(a.revision||1))}
function usageAvatars(r){return `<div class="usage-avatars">${r.users.slice(0,3).map(name=>`<span class="expert-avatar" title="${esc(name)}">${initials(name)}</span>`).join('')}${r.users.length>3?`<span class="expert-avatar">+${r.users.length-3}</span>`:''}${!r.users.length?'<span class="empty-avatar">—</span>':''}</div><strong>${r.users.length} viewers</strong><p>${r.subscribed?'24 employees covered by company subscription':'0 people covered by company subscription'}${r.id.startsWith('example')?' · Demo':''}</p>`}
const basePoolDetail=poolDetail;
poolDetail=function(r){const versions=skillVersions(r);const selected=versions.find(v=>v.revision===kb.version)||versions[0];const html=basePoolDetail({...r,...selected});return html.replace(/<article><span>USAGE<\/span>[\s\S]*?<\/article>/,`<article><span>PEOPLE & ACCESS</span>${usageAvatars(r)}</article>`).replace('Covered by the company knowledge plan.','Subscribed by Demo Company for employees, including new hires.').replace('The company has not paid for access to this skill.','Company access is not active. New employees need a company subscription; you retain free author access.').replace('<div class="skill-detail-columns">',`<section class="version-panel"><div><h2>Version history <span>${Math.max(0,versions.length-1)} updates</span></h2><p>Choose the version you prefer. Downloads keep that version.</p></div><div class="version-options">${versions.map((v,i)=>`<button data-action="pool-version:${v.revision}" class="${v.revision===selected.revision?'active':''}"><strong>Version ${v.revision||1}${i===0?' · Latest':''}</strong><small>${esc(v.versionNote)}</small></button>`).join('')}</div></section><div class="skill-detail-columns">`)};
const basePoolMarkup=poolMarkup;
poolMarkup=function(){return kb.view==='downloads'?`<section class="company-pool"><header class="pool-heading"><span class="eyebrow">YOUR SAVED SKILLS</span><h1>Downloads</h1><p>The knowledge you downloaded, with the version you chose.</p></header><div class="download-list">${savedDownloads.length?savedDownloads.map((d,i)=>`<article class="download-row"><div class="download-file">${icon('file')}</div><div><h2>${esc(d.title)}</h2><p>Version ${d.revision||1} · ${esc(d.author)} · ${new Date(d.downloadedAt).toLocaleDateString('en-US')}</p><small>Saved copy · SKILL.md</small></div><button class="button" data-action="pool-redownload:${i}">Download again</button><button class="button ghost" data-action="pool-open:${d.id}">View in Pool</button></article>`).join(''):'<div class="pool-empty"><h2>Your skills will appear here.</h2><p>Download a skill from the Pool to keep a versioned copy.</p><button class="button" data-action="pool-back-list">Browse Pool</button></div>'}</div></section>`:basePoolMarkup()};
function downloadVersion(r,remember=true){const text=`---\nname: ${r.title.toLowerCase().replace(/[^a-z0-9]+/g,'-')}\ndescription: ${JSON.stringify(r.summary)}\n---\n\n# ${r.title}\n\nVersion: ${r.revision||1}\nAuthor: ${r.author}\n\n${r.id.startsWith('example')?'Illustrative prototype skill. Review before real use.':'Reviewed captured knowledge.'}\n\n## Steps\n${r.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n\n${r.answers?'## Reasoning and validation\n'+r.answers.join('\n\n'):''}\n${r.code?'## Captured code\n```\n'+r.code+'\n```':''}`;const url=URL.createObjectURL(new Blob([text],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download='SKILL.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);if(remember){savedDownloads=savedDownloads.filter(d=>!(d.id===r.id&&d.revision===r.revision));savedDownloads.unshift({...r,downloadedAt:Date.now()});try{localStorage.setItem('hypercubic-downloads',JSON.stringify(savedDownloads))}catch{}}animateDownloadArrival();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const [action,id]=b.dataset.action.split(':');if(action==='pool-open')kb.version=null;if(!['pool-download','pool-downloads','pool-version','pool-redownload','pool-back-list'].includes(action))return;e.stopImmediatePropagation();if(action==='pool-download'){const r=companyItems().find(r=>r.id===id);if(!r||!(r.own||r.subscribed))return;const versions=skillVersions(r);downloadVersion(versions.find(v=>v.revision===kb.version)||versions[0]);return}if(action==='pool-redownload'){const r=savedDownloads[Number(id)];if(r)downloadVersion(r,false);return}if(action==='pool-version')kb.version=Number(id);if(action==='pool-downloads'){kb.view='downloads';kb.drawer=null;kb.poolNotice=null;history.replaceState(null,'','#downloads')}if(action==='pool-back-list'){kb.view='pool';kb.poolItem=null;history.replaceState(null,'','#pool')}render()},true);
if(location.hash==='#downloads'){state.screen='knowledge';kb.view='downloads';kb.loading=false}
if(state.screen==='knowledge')render();

function animateDownloadArrival(){const target=document.querySelector('.rail-downloads');if(!target)return;document.querySelectorAll('.download-flight,.download-arrival-tip').forEach(n=>n.remove());const origin=document.querySelector('.skill-primary-actions .primary')||document.activeElement;const end=target.getBoundingClientRect(),start=origin?.getBoundingClientRect?.()||end;const arrive=()=>{target.classList.remove('download-landed');void target.offsetWidth;target.classList.add('download-landed');const tip=document.createElement('button');tip.className='download-arrival-tip';tip.textContent='Saved in Downloads  →';tip.setAttribute('aria-label','Open Downloads');tip.style.left=(end.right+14)+'px';tip.style.top=(end.top-2)+'px';tip.onclick=()=>{tip.remove();target.click()};document.body.appendChild(tip);setTimeout(()=>tip.remove(),4500);setTimeout(()=>target.classList.remove('download-landed'),1200)};if(matchMedia('(prefers-reduced-motion: reduce)').matches){arrive();return}const flight=document.createElement('div');flight.className='download-flight';flight.innerHTML=icon('file');flight.setAttribute('aria-hidden','true');flight.style.left=(start.left+start.width/2-18)+'px';flight.style.top=(start.top+start.height/2-18)+'px';document.body.appendChild(flight);const dx=end.left+end.width/2-(start.left+start.width/2),dy=end.top+end.height/2-(start.top+start.height/2);const animation=flight.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.45}px,${dy*.2-70}px) scale(.85)`,opacity:1,offset:.45},{transform:`translate(${dx}px,${dy}px) scale(.25)`,opacity:.3}],{duration:850,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});animation.onfinish=()=>{flight.remove();arrive()}}
